# 以下是当前场景时间下剧情相关的最新世界和人物动态
<世界动态信息>
═══════ 以下是上期世界动态 ═══════
<%_
function stripAddonForDisplay(data) {
  if (data == null || typeof data !== 'object' || Array.isArray(data)) return data;
  const HIDDEN = new Set(['平行演化']);
  function stripDeep(value) {
    if (value == null || typeof value !== 'object') return value;
    if (Array.isArray(value)) return value.map(stripDeep);
    const next = {};
    for (const [k, v] of Object.entries(value)) {
      if (HIDDEN.has(k)) continue;
      next[k] = stripDeep(v);
    }
    return next;
  }
  return stripDeep(_.cloneDeep(data));
}

const addonData = getvar('addon_data');
const addonUi = getvar('addon_ui') || {};
const planeMerge = addonUi.位面交汇 === true;
const isEmpty = !addonData || Object.keys(addonData || {}).length === 0;

let primaryWorld = null; // 降临===true → <上期世界状态>
let otherWorlds = null;  // 仅位面交汇时，其余世界 → <上期其它世界状态>

if (!isEmpty) {
  const stripped = stripAddonForDisplay(addonData);
  if (stripped != null && typeof stripped === 'object' && !Array.isArray(stripped)) {
    const descended = {};
    const others = {};
    for (const [name, world] of Object.entries(stripped)) {
      if (world && typeof world === 'object' && !Array.isArray(world) && world.降临 === true) {
        descended[name] = world;
      } else {
        others[name] = world;
      }
    }
    if (Object.keys(descended).length > 0) primaryWorld = descended;
    if (planeMerge && Object.keys(others).length > 0) otherWorlds = others;
  }
}
_%>
<%_ if (primaryWorld) { _%>
<上期世界状态>
<%- YAML.stringify(primaryWorld, { blockQuote: 'literal' }) %>
</上期世界状态>
<%_ } _%>
<%_ if (otherWorlds) { _%>
<上期其它世界状态>
<%- YAML.stringify(otherWorlds, { blockQuote: 'literal' }) %>
</上期其它世界状态>
<%_ } _%>
═══════ 上期世界动态结束，以下是上轮不在场角色的后台动态 ═══════

{{后台角色行动时间段}}
<上轮后台角色动态>
{{total:launched:npc@act}}
</上轮后台角色动态>

═══════ 上轮不在场角色后台动态结束，以下是本轮不在场关系列表角色的完整信息 ═══════

<%_ {
  const data = getMessageVar('stat_data', { defaults: {} });
  const relations = _.get(data, '关系列表', {});
  const absentChars = _.pickBy(relations, char => char.在场 === false);
_%>
<不在场角色>
<%= YAML.stringify({ 关系列表: absentChars }, { blockQuote: 'literal' }) _%>
</不在场角色>
<%_ } _%>

═══════ 世界动态信息结束 ═══════
</世界动态信息>

